#include <bits/stdc++.h>
using namespace std;

int Next() {
    int c;
    int res = 0;
    do {
        c = getchar();
        if (c == EOF)
            return res;
    } while (c < '0' || c > '9');
    res = c - '0';
    while (true) {
        c = getchar();
        if (c < '0' || c > '9')
            return res;
        res *= 10;
        res += c - '0';
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n = Next();
    int m = Next();

    vector<int> a(m);
    vector<int> b(m);
    for (int i = 0; i < m; i++) {
        a[i] = Next();
        b[i] = Next();
    }

    vector<pair<int,int>> v(m);
    for (int i = 0; i < m; i++) {
        v[i] = {b[i], a[i]};
    }
    sort(v.begin(), v.end());

    for (int i = 0; i < m; i++) {
        b[i] = v[i].first;
        a[i] = v[i].second;
    }

    int sum = 0;
    for (int i = m - 1; i >= 0; i--) {
        if (a[i] < n) {
            sum += a[i] * b[i];
            n -= a[i];
        } else {
            sum += n * b[i];
            break;
        }
    }

    cout << sum << '\n';
    return 0;
}

